<template><div v-if="value"><p>计算时间：{{ value.evaluatedAt }}<span v-if="value.validUntil"> · 下一条件边界：{{ value.validUntil }}</span></p><Row :gutter="16"><Col v-for="tier in tiers" :key="tier.key" :span="8"><Card><h3>{{ tier.title }}</h3><Tag :color="value[tier.flag]?'green':'orange'">{{ value[tier.flag]?'条件满足':'待补条件' }}</Tag><ul><li v-for="(reason,index) in reasons(value,tier.key)" :key="index">{{ label(reason.code) }} <small v-if="reason.objectId">{{ reason.objectId }}</small><Button v-if="target(reason)" size="small" type="text" @click="go(reason)">{{target(reason).label}}</Button><small v-else> · 请联系负责此项的平台人员</small></li></ul></Card></Col></Row><p>基础经营、模拟资格和真实资格分别判断；当前来源：{{ value.environment }} / {{ value.authorizedMode }}</p><Card v-for="category in value.categories||[]" :key="category.categoryId" class="s1-category"><h3>经营类目 {{category.categoryName||category.categoryId}}</h3><p>此类目的条件独立判断；店铺基础条件满足不代表全部类目可售。</p><div v-for="tier in tiers" :key="tier.key"><strong>{{tier.title}}</strong> <Tag :color="category[tier.flag]?'green':'orange'">{{category[tier.flag]?'条件满足':'待补条件'}}</Tag><ul><li v-for="(reason,index) in reasons(category,tier.key)" :key="index">{{label(reason.code)}} <small>{{reason.objectId}}</small><Button v-if="target(reason)" size="small" type="text" @click="go(reason)">{{target(reason).label}}</Button><small v-else> · 请联系负责此项的平台人员</small></li></ul></div></Card></div></template>
<script>import {label} from './shared';import {managerAccess} from '@/libs/manager-access';import {eligibilityTarget} from './eligibility-navigation';export default {props:{value:Object},data:()=>({tiers:[{key:'BASIC',flag:'BASIC_ELIGIBLE',title:'基础经营条件'},{key:'MOCK',flag:'MOCK_READY',title:'模拟交易前置条件'},{key:'REAL',flag:'REAL_READY',title:'真实渠道前置条件'}]}),methods:{label,target(reason){return eligibilityTarget(reason.code,action=>managerAccess.has(action));},go(reason){const target=this.target(reason);if(target){const sources=this.value.sourceVersions||{},channel=Object.values(sources).find(row=>row&&row.configId&&row.id===reason.objectId);this.$router.push({path:target.path,query:{targetStore:this.value.storeId,...(channel?{configId:channel.configId}:{})}});}},reasons(value,key){return value.reasons&&value.reasons[key]||[];}}};</script>
<style scoped>h3{margin-bottom:12px}p{margin:14px 0}ul{padding-left:18px;line-height:1.8}small{word-break:break-all;color:#777}</style>
